\label{thm:eif}
		\begin{itemize}
			\item[(i)] The EIF for $\lambda_{C,a}$ is
			\begin{align*}
				&\varphi_{C,a}(\mathcal{O})=\frac{\mathbbm{1}(A=a)}{\pi^a(1-\pi)^{1-a}}\left[\mathfrak{w}_{C,a,a}(\mathbf Y)-\mathbb{E}\left\{\mathfrak{w}_{C,a,a}(\mathbf Y)|\mathbf X,\bm{C},N,A=a\right\}\right]\displaybreak[0]\\
				&~+\frac{\mathbbm{1}(A=1-a)}{\pi^{1-a}(1-\pi)^a}\left[\mathfrak{w}_{C,a,1-a}(\mathbf Y)-\mathbb{E}\left\{\mathfrak{w}_{C,a,1-a}(\mathbf Y)|\mathbf X,\bm{C},N,A=1-a\right\}\right]\displaybreak[0]\\
				&~+\mathbb{E}\left\{\mathfrak{w}_{C,a,a}(\mathbf Y)|\mathbf X,\bm{C},N,A=a\right\}+\mathbb{E}\left\{\mathfrak{w}_{C,a,1-a}(\mathbf Y)|\mathbf X,\bm{C},N,A=1-a\right\}-2\lambda_{C,a},
			\end{align*}
			where $\mathfrak{w}_{C,a,a}(\mathbf y)=\mathbb{E}\{\overline w(\mathbf y,\mathbf Y_k)|A_k=1-a\}$ and $\mathfrak{w}_{C,a,1-a}(\mathbf y)=\mathbb{E}\{\overline w(\mathbf Y_k,\mathbf y)|A_k=a\}$.
			\item[(ii)] The EIF for $\lambda_{I,a}$ is
			\begin{align*}
				&\varphi_{I,a}(\mathcal{O})=\frac{\mathbbm{1}(A=a)N}{\pi^a(1-\pi)^{1-a}\{\mathbb{E}(N)\}^2}\left[\mathfrak{w}_{I,a,a}(\mathbf Y)-\mathbb{E}\left\{\mathfrak{w}_{I,a,a}(\mathbf Y)|\mathbf X,\bm{C},N,A=a\right\}\right]\displaybreak[0]\\
				&~+\frac{\mathbbm{1}(A=1-a)N}{\pi^{1-a}(1-\pi)^a\{\mathbb{E}(N)\}^2}\left[\mathfrak{w}_{I,a,1-a}(\mathbf Y)-\mathbb{E}\left\{\mathfrak{w}_{I,a,1-a}(\mathbf Y)|\mathbf X,\bm{C},N,A=1-a\right\}\right]\displaybreak[0]\\
				&~+\frac{N}{\{\mathbb{E}(N)\}^2}\left[\mathbb{E}\left\{\mathfrak{w}_{I,a,a}(\mathbf Y)|\mathbf X,\bm{C},N,A=a\right\}+\mathbb{E}\left\{\mathfrak{w}_{I,a,1-a}(\mathbf Y)|\mathbf X,\bm{C},N,A=1-a\right\}\right]\displaybreak[0]\\
				&~-\frac{2N\lambda_{I,a}}{\mathbb{E}(N)},
			\end{align*}
			where $\mathfrak{w}_{I,a,a}(\mathbf y)=\mathbb{E}\{N_k\overline w(\mathbf y,\mathbf Y_k)|A_k=1-a\}$ and $\mathfrak{w}_{I,a,1-a}(\mathbf y)=\mathbb{E}\{N_k\overline w(\mathbf Y_k,\mathbf y)|A_k=a\}$.
		\end{itemize}

\label{ex:PIM}
		Consider the setting where $w(\bm{Y}_{ij},\bm{Y}_{kl})=\mathbbm{1}(\bm{Y}_{ij}\preceq_P \bm{Y}_{kl})$, the Pareto partial order contrast function discussed in Example \ref{ex:pareto}. To implement the above strategy for a PIM working model for $\zeta_{ik,a}=\mathbb{E}\{\overline w(\mathbf Y_i,\mathbf Y_k)|A_i=a,A_k=1-a,\mathbf X_i,\mathbf X_k,\bm{C}_i,\bm{C}_k,N_i,N_k\}$, let $\bm{U}_{ij}=(A_i,\bm{X}_{ij}^\top,\overline{\mathbf X}_i^\top,\bm{C}_i^\top, N_i)^\top$. Then, we adopt the following model:
		\begin{align*}
			&g[\mathbb{E}\{\mathbbm{1}(\bm{Y}_{ij}\preceq_P \bm{Y}_{kl})|\bm{U}_{ij},\bm{U}_{kl}\}] = (\bm{U}_{ij}-\bm{U}_{kl})^\top\bm{\vartheta} = (A_i-A_k)\beta_A + (\bm{X}_{ij}-\bm{X}_{kl})^\top\bm{\beta}_{\bm{X}}\displaybreak[0]\\
			&+(\overline{\mathbf X}_i-\overline{\mathbf X}_k)^\top\bm{\beta}_{\overline{\mathbf X}} + (\bm{C}_i-\bm{C}_k)^\top\bm{\beta}_{\bm{C}} + (N_i-N_k)\beta_N,
		\end{align*}
		where $A_i=a$, $A_k=1-a$, and $\bm{\vartheta} = (\beta_A, \bm{\beta}_{\bm{X}}^\top, \bm{\beta}_{\overline{\mathbf X}}^\top, \bm{\beta}_{\bm{C}}^\top, \beta_N)^\top$. Fitting the above model with $\mathbbm{1}(\bm{Y}_{ij}\preceq_P \bm{Y}_{kl})$ on $\bm{U}_{ij}-\bm{U}_{kl}$, we obtain $\widehat\mathbb{E}\{\mathbbm{1}(\bm{Y}_{ij}\preceq_P \bm{Y}_{kl})|\bm{U}_{ij},\bm{U}_{kl}\}=g^{-1}\{(\bm{U}_{ij}-\bm{U}_{kl})^\top\widehat\bm{\vartheta}\}$, where $\widehat\bm{\vartheta} = (\widehat\beta_A, \widehat\bm{\beta}_{\bm{X}}^\top, \widehat\bm{\beta}_{\overline{\mathbf X}}^\top, \widehat\bm{\beta}_{\bm{C}}^\top, \widehat\beta_N)^\top$. The estimate of $\zeta_{ik,a}$ is obtained by taking average over each pair of $(i,j)$ and $(k,l)$ for fixed $i$ and $k$, i.e., $\widehat\zeta_{ik,a}=(N_iN_k)^{-1}\sum_{j=1}^{N_i}\sum_{l=1}^{N_k}\widehat\mathbb{E}\{\mathbbm{1}(\bm{Y}_{ij}\preceq_P \bm{Y}_{kl})|\bm{U}_{ij},\bm{U}_{kl}\}=(N_iN_k)^{-1}\sum_{j=1}^{N_i}\sum_{l=1}^{N_k}g^{-1}\{(\bm{U}_{ij}-\bm{U}_{kl})^\top\widehat\bm{\vartheta}\}$.

Consider a setting where $m=10$ and $|\mathfrak{I}^s|=3$. We can first form the partition $\mathfrak{I}^{\mathrm{si}}=\{\mathcal{I}_1^{\mathrm{si}},\mathcal{I}_2^{\mathrm{si}},\mathcal{I}_3^{\mathrm{si}}\}$ with $\mathcal{I}_1^{\mathrm{si}}=\{1,2,3\}$, $\mathcal{I}_2^{\mathrm{si}}=\{4,5,6,7\}$, and $\mathcal{I}_3^{\mathrm{si}}=\{8,9,10\}$. Then, the partition $\mathfrak{I}^{\mathrm{pr}}$ is formed as $\{(\mathcal{I}_1^{\mathrm{si}},\mathcal{I}_1^{\mathrm{si}}),(\mathcal{I}_1^{\mathrm{si}},\mathcal{I}_2^{\mathrm{si}}),(\mathcal{I}_1^{\mathrm{si}},\allowbreak\mathcal{I}_3^{\mathrm{si}}),(\mathcal{I}_2^{\mathrm{si}},\mathcal{I}_2^{\mathrm{si}}),(\mathcal{I}_2^{\mathrm{si}},\mathcal{I}_3^{\mathrm{si}}),(\mathcal{I}_3^{\mathrm{si}},\mathcal{I}_3^{\mathrm{si}})\}$. For $\mathfrak{I}^{\mathrm{pr}}$, elements formed by $\mathcal{I}_{s_1}^{\mathrm{si}}$ and $\mathcal{I}_{s_2}^{\mathrm{si}}$ with $s_1<s_2$ are the Cartesian product of $\mathcal{I}_{s_1}^{\mathrm{si}}$ and $\mathcal{I}_{s_2}^{\mathrm{si}}$. For instance, 
		\begin{align*}
			(\mathcal{I}_1^{\mathrm{si}},\mathcal{I}_2^{\mathrm{si}})=\{(1,4),(1,5),(1,6),(1,7),(2,4),(2,5),(2,6),(2,7),(3,4),(3,5),(3,6),(3,7)\}.
		\end{align*}
		Elements formed by $\mathcal{I}_s^{\mathrm{si}}$ itself need to exclude pairs consisting of the same indices, e.g., $(\mathcal{I}_1^{\mathrm{si}},\mathcal{I}_1^{\mathrm{si}})=\{(1,2),(1,3),(2,3)\}$. According to this sampling-splitting scheme, all $\binom{10}{2}=45$ possible pairs are divided into $|\mathfrak{I}^{\mathrm{pr}}|=6$ subsets.
